package io.knowledgebrain.collaboration;
import java.util.*;import java.time.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
import org.springframework.mock.web.MockHttpServletRequest;import org.springframework.web.server.ResponseStatusException;import io.micrometer.core.instrument.simple.SimpleMeterRegistry;
class AssignmentApiTest {
 StudyApiTest f;AssignmentStore store;AssignmentController api;UUID study;
 @BeforeEach void setup(){f=new StudyApiTest();f.setup();study=new UuidV7(Clock.systemUTC()).next();store=mock(AssignmentStore.class);api=new AssignmentController(store,f.api,new SimpleMeterRegistry());}
 MockHttpServletRequest req(String method,String body){var r=f.req(method,body);r.removeHeader("If-Match");r.addHeader("If-Match","\"as1\"");return r;}
 String settings(){return "{\"title\":\"Assignment\",\"description\":\"Instructions\"}";}
 @Test void memberViewerMayReadAllStatesButNeverMutate()throws Exception{
  for(String role:List.of("MEMBER","VIEWER")){f.role(role);when(store.list(f.group,f.space,study,null,20)).thenReturn(new AssignmentStore.Page(List.of(),null));assertEquals(200,api.list(f.group.toString(),study.toString(),req("GET",null)).getStatusCode().value());assertEquals(403,assertThrows(ResponseStatusException.class,()->api.create(f.group.toString(),study.toString(),req("POST",settings()))).getStatusCode().value());assertThrows(ResponseStatusException.class,()->api.metadata(f.group.toString(),study.toString(),f.id.toString(),req("PUT",settings())));assertThrows(ResponseStatusException.class,()->api.state(f.group.toString(),study.toString(),f.id.toString(),req("PUT","{\"state\":\"OPEN\"}")));assertThrows(ResponseStatusException.class,()->api.retire(f.group.toString(),study.toString(),f.id.toString(),req("DELETE",null)));}verify(store,never()).create(any(),any(),any(),any(),any(),any(),any(),any());
 }
 @Test void freshParticipationDenialAndMismatchedSpaceNeverReachStore(){
  when(f.auth.participation(any(),anyList(),anyString())).thenReturn(new GroupSpaceClient.Access(f.actor,"REGISTERED",List.of()));assertEquals(404,assertThrows(ResponseStatusException.class,()->api.list(f.group.toString(),study.toString(),req("GET",null))).getStatusCode().value());when(f.auth.participation(any(),anyList(),anyString())).thenReturn(new GroupSpaceClient.Access(f.actor,"REGISTERED",List.of(new GroupSpaceClient.Grant(f.group,f.id,"OWNER","PRIVATE"))));assertThrows(ResponseStatusException.class,()->api.list(f.group.toString(),study.toString(),req("GET",null)));verifyNoInteractions(store);
 }
 @Test void credentialsOriginAndBodyBoundsRejectBeforePersistence(){
  var insecure=req("POST",settings());insecure.setSecure(false);var duplicate=req("POST",settings());duplicate.addHeader("Cookie","__Host-brain_guest="+f.token);var origin=req("POST",settings());origin.addHeader("Origin","https://elsewhere.example");for(var r:List.of(insecure,duplicate,origin))assertThrows(ResponseStatusException.class,()->api.create(f.group.toString(),study.toString(),r));verifyNoInteractions(f.auth,store);
  var large=req("POST","x".repeat(65537));assertEquals(413,assertThrows(ResponseStatusException.class,()->api.create(f.group.toString(),study.toString(),large)).getStatusCode().value());var type=req("POST",settings());type.setContentType("text/plain");assertEquals(415,assertThrows(ResponseStatusException.class,()->api.create(f.group.toString(),study.toString(),type)).getStatusCode().value());
 }
 @Test void strictInputsAndIndependentAssignmentPreconditionsRejectAmbiguity(){
  for(String body:List.of("{}",settings()+" {}",settings().replace("Assignment",""),"{\"title\":\"A\",\"title\":\"B\",\"description\":\"\"}",settings().replace("Instructions\"}","Instructions\",\"actorId\":\"spoof\"}")))assertThrows(ResponseStatusException.class,()->api.create(f.group.toString(),study.toString(),req("POST",body)));
  for(String tag:List.of("*","W/\"as1\"","\"st1\"","\"as0\"","\"as9999999999999999999\"")){var r=req("PUT",settings());r.removeHeader("If-Match");r.addHeader("If-Match",tag);assertThrows(ResponseStatusException.class,()->api.metadata(f.group.toString(),study.toString(),f.id.toString(),r));}var absent=req("DELETE",null);absent.removeHeader("If-Match");assertEquals(428,assertThrows(ResponseStatusException.class,()->api.retire(f.group.toString(),study.toString(),f.id.toString(),absent)).getStatusCode().value());
  var q=req("GET",null);q.addParameter("token","bad");assertThrows(ResponseStatusException.class,()->api.list(f.group.toString(),study.toString(),q));assertThrows(ResponseStatusException.class,()->api.list(f.group.toString(),study.toString(),req("GET","{}")));for(String state:List.of("DRAFT","ACTIVE","RETIRED","OPEN\",\"actorId\":\"spoof"))assertThrows(ResponseStatusException.class,()->api.state(f.group.toString(),study.toString(),f.id.toString(),req("PUT","{\"state\":\""+state+"\"}")));verifyNoInteractions(store);
 }
 @Test void createReturnsScopedLocationNoStoreAndStableVersion()throws Exception{
  var v=new AssignmentStore.Assignment(f.id,study,f.group,f.space,f.actor,1,"Assignment","Instructions","DRAFT","PRIVATE",Instant.now().toString(),Instant.now().toString());when(store.create(eq(f.group),eq(f.space),eq(study),eq(f.actor),eq("a".repeat(32)),eq("Assignment"),eq("Instructions"),anyString())).thenReturn(new AssignmentStore.Result(v,true),new AssignmentStore.Result(v,false));var first=api.create(f.group.toString(),study.toString(),req("POST",settings()));var retry=api.create(f.group.toString(),study.toString(),req("POST",settings()));assertEquals(201,first.getStatusCode().value());assertEquals(200,retry.getStatusCode().value());assertEquals("\"as1\"",first.getHeaders().getETag());assertEquals("no-store",first.getHeaders().getCacheControl());assertEquals("/api/groups/"+f.group+"/studies/"+study+"/assignments/"+f.id,first.getHeaders().getLocation().toString());assertEquals(first.getBody(),retry.getBody());
 }
}
